where r.tenant_id = #{scopedTenantId} and ifnull(r.del_flag, 0) = 0
 and r.period_id = #{periodId}
 and r.report_mode = #{reportMode}
 and r.material_id = #{materialId}
 and r.jc_type_id = #{jcTypeId}
 and m.code like concat('%', #{materialCode}, '%')
 and m.name like concat('%', #{materialName}, '%')
 and t.code like concat('%', #{jcTypeCode}, '%')
 and t.name like concat('%', #{jcTypeName}, '%')
order by r.period_id desc, r.id desc



